function ui_input(string $label,string $name,mixed $value='',string $type='text',bool $required=false,string $hint=''): void {
  if($_SERVER['REQUEST_METHOD']==='POST' && array_key_exists($name,$_POST))$value=post($name,40000);
  echo '<label>'.e($label);
  if($type==='textarea')echo '<textarea name="'.e($name).'" rows="'.(in_array($name,['body','pseo_body'],true)?16:4).'" '.($required?'required':'').'>'.e(str_replace('\\n',"\n",(string)$value)).'</textarea>';
  else echo '<input type="'.e($type).'" name="'.e($name).'" value="'.e($value).'" '.($required?'required':'').'>';
  if($hint)echo '<small class="field-hint">'.e($hint).'</small>';echo '</label>';
}
function ui_select(string $label,string $name,array $options,mixed $value=''): void {echo '<label>'.e($label).'<select name="'.e($name).'">';foreach($options as $key=>$text)echo '<option value="'.e($key).'" '.((string)$value===(string)$key?'selected':'').'>'.e($text).'</option>';echo '</select></label>';}
function ui_check(string $label,string $name,bool $checked): void {echo '<label class="check"><input type="checkbox" name="'.e($name).'" '.($checked?'checked':'').'><span>'.e($label).'</span></label>';}
function media_select(string $name,int $value=0): void {$options=[0=>'Görsel seçilmedi'];foreach(cms_records('media') as $m)$options[$m['id']]=$m['original_name'].' (#'.$m['id'].')';ui_select('Görsel / medya kütüphanesi',$name,$options,$value);}
function action_fields(string $action,array $values=[]): void {echo csrf_field().'<input type="hidden" name="action" value="'.e($action).'">';foreach($values as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';}
function remove_button(string $table,int $id,bool $cms=false): void {echo '<form method="post" class="inline-form" data-confirm="Bu kayıt silinsin mi?">';action_fields($cms?'cms_delete':'delete',['table'=>$table,'id'=>$id]);echo '<button class="link-danger">Sil</button></form>';}
function checks_html(array $checks): void {echo '<div class="checklist">';foreach($checks as $label=>$ok)echo '<div class="'.($ok?'pass':'fail').'">'.($ok?'✓':'!').' '.e($label).'</div>';echo '</div>';}
