iv><div class="table-pagination" data-pagination></div><?php if($tab==='pages'): ?><div class="bulk-actions"><select form="bulk-form" name="status" aria-label="Toplu işlem"><option value="published">İncelenenleri yayınla</option><option value="draft">Taslağa al</option></select><button form="bulk-form" class="button dark">Seçilene uygula</button></div><?php endif; ?><?php endif; ?></section>
